from lib import *
S = SS('p39')
steps = [
    step("合成语料(随机词表,不是真实网页):150 篇原文各 400 个词,每篇另有改了 1%、5%、15% 的词的 3 个变体,另有 150 篇互不相关的文章,共 750 篇;所有页面共用同一段 600 词的站点模板(导航、页脚)。正例是“原文-变体”共 450 对;负例是不同组的文章共 279,975 对。", t=tl(S(1)), done=lidx(S(1), '150 篇原文'), kv=KV([['原文', '150 篇 × 400 词'], ['变体', '每篇 3 个(改 1%、5%、15%)'], ['站点模板', '600 词,所有页面共用']], ['站点模板'])),
    step("64 位 SimHash 的汉明距离。只对正文:原文与改 1% 的变体最小 0、中位 1、最大 8;与改 5% 的中位 4、最大 9;与改 15% 的中位 7、最大 15;互不相关的两篇中位 18、最小 4、最大 36。把共用的 600 词站点模板也一起做:原文与变体的距离更小(中位 0、1、2),但互不相关的两篇也被拉近了,中位只有 6、最小 0、最大 15。对照:原文与变体的词集合 Jaccard 平均 0.869,随机两篇平均 0.150。", t=tl(S(2)), done=lidx(S(2), '原文 与 改 1%', '原文 与 改 5%', '原文 与 改 15%'), mark=lidx(S(2), '互不相关的两篇'), b=bars([['不相关两篇:只对正文(中位)', 18, '18'], ['不相关两篇:含模板(中位)', 6, '6'], ['改 15%:只对正文(中位)', 7, '7'], ['改 15%:含模板(中位)', 2, '2']], 20, mark=[1], done=[0, 2]), kv=KV([['只对正文', '不相关中位 18,改 15% 中位 7'], ['含站点模板', '不相关中位只有 6'], ['原因', '共用的模板把所有页面拉近']], ['原因'])),
    step("选阈值 k(汉明距离 ≤ k 判为近似重复),共 450 对正例、279,975 对负例。只对正文:k=3 召回 47.6%、误报 0;k=6 召回 76.0%、误报 50 对;k=10 召回 96.9%、误报 2968;k=14 召回 99.8%、误报 38029。含站点模板:k=0 召回 31.6%、误报 275 对;k=3 召回 93.1% 但误报 37005 对(把 13% 的无关文章对都判为重复);k=6 召回 100%、误报 194111 对。模板文字不去掉,近似去重会把整个站点的页面当成重复。", t=tl(S(3)), done=lidx(S(3), '  3  ', '  6  ', ' 10  '), mark=lidx(S(3), '  0  ', ' 14  '), b=bars([['只对正文 k=3:误报对数', 0, '0'], ['含模板 k=3:误报对数', 37005, '37005'], ['只对正文 k=10:误报', 2968, '2968']], 38000, mark=[1], done=[0]), kv=KV([['只对正文 k=3', '召回 47.6%,误报 0'], ['含模板 k=3', '召回 93.1%,误报 37005'], ['k=10(只对正文)', '召回 96.9%,误报 2968']], ['含模板 k=3'])),
    step("用词的 3 元组(shingle)当特征代替单个词:只对正文时原文与改 5% 的距离中位 11(最大 21),改 15% 中位 19(最大 27),不相关的两篇中位 32(最小 14、最大 50);含模板时不相关的两篇中位 20(最小 5)。3 元组让相同与不同拉开了更远(不相关中位 32 对 改 5% 中位 11),但对同样的编辑,变体之间的距离也更大,阈值要重新选。", t=tl(S(4)), done=lidx(S(4), '只对正文(3 元组)'), mark=lidx(S(4), '含模板(3 元组)'), b=bars([['3 元组·不相关(中位)', 32, '32'], ['3 元组·改 5%(中位)', 11, '11'], ['3 元组·改 15%(中位)', 19, '19']], 35, done=[0, 1, 2]), kv=KV([['3 元组 不相关', '中位 32'], ['3 元组 改 5%', '中位 11'], ['注意', '阈值要重新选']], ['注意'])),
    step("速度(纯 Python):400 词文章的 SimHash 约 1.47 ms/篇;两两比较 280,875 对汉明距离用了 0.07 秒(约 3.90 百万对/秒)。两两比较是 O(n²),文章数到百万级就要用索引把可能近似的先筛出来;这里没有实现和测试索引。", t=tl(S(5)), done=lidx(S(5), '计算 400 词文章的 SimHash'), kv=KV([['计算 SimHash', '1.47 ms / 篇'], ['两两比较', '3.90 百万对 / 秒'], ['百万篇', 'O(n²) 不可行,需要索引']], ['百万篇'])),
]
